#include <stdlib.h>

int reallocate_array(void *ptr, size_t nmemb, size_t size) {
    void **p = (void **)ptr;
    void *new_ptr = realloc(*p, nmemb * size);

    if (!new_ptr && nmemb * size != 0) {
        return AVERROR(ENOMEM);
    }

    *p = new_ptr;
    return 0;
}
